import { Note } from "@canvasview/kit";

type Data = { emailId: string; from: string; subject: string; received: string; body: string };

// One email, opened from an inbox: the open input is its data.
export default function EmailReader({ data }: { data: Data }) {
  return (
    <article style={{ display: "grid", gap: 8, padding: 12 }}>
      <h2 style={{ margin: 0 }}>{data.subject}</h2>
      <p style={{ margin: 0 }}>From {data.from}, {data.received}</p>
      <Note markdown={data.body} />
    </article>
  );
}

