import { useState } from "react";
import { canvas, useSharedState } from "@canvasview/kit";

type Email = { emailId: string; from: string; subject: string; received: string; body: string };
type Data = { emails: Email[] };

// Opens each email beside the inbox, for everyone, as the node's opens declares: canvas.open("email", email) opens
// the saved email-reader with the email as its data. The same emailId again brings back the one already open.
export default function Inbox({ data }: { data: Data }) {
  const [archived, setArchived, { error }] = useSharedState<string[]>("inbox.archived", []);
  // Only this viewer's: why their own open failed.
  const [failed, setFailed] = useState<string | null>(null);
  const emails = data.emails.filter((email) => !archived.includes(email.emailId));

  function open(email: Email) {
    canvas.open("email", email).then(() => setFailed(null), (reason: { reason?: string }) => setFailed(reason.reason ?? "unavailable"));
  }
  // Archiving takes the email off the list, and its reader off the canvas: canvas.remove removes this inbox's own instance.
  function archive(email: Email) {
    setArchived((current) => [...current, email.emailId]);
    canvas.remove("email", email.emailId).catch(() => undefined);
  }

  return (
    <div style={{ display: "grid", gap: 8, padding: 12 }}>
      {failed ? <p role="alert">Could not open that email ({failed}).</p> : null}
      {error ? <p role="alert">Could not archive ({error}).</p> : null}
      <ul style={{ listStyle: "none", margin: 0, padding: 0, display: "grid", gap: 4 }}>
        {emails.map((email) => (
          <li key={email.emailId} style={{ display: "flex", gap: 8, alignItems: "baseline" }}>
            <button type="button" onClick={() => open(email)} style={{ flex: 1, textAlign: "start" }}>
              <strong>{email.from}</strong> {email.subject} <small>{email.received}</small>
            </button>
            <button type="button" onClick={() => archive(email)} aria-label={`Archive ${email.subject}`}>Archive</button>
          </li>
        ))}
      </ul>
      {emails.length ? null : <p>Nothing left in the inbox.</p>}
    </div>
  );
}
